import { describe, expect, it } from 'vitest'
import { Engine } from './engine'
import { DEFAULT_PARAMS, PRESETS, clampParam, type Params } from './params'
import { CONST, DT } from './world'
import { findPeaks, movingAverage, bestLag, summarise } from './analysis'

function run(params: Partial<Params>, seconds: number) {
  const engine = new Engine({ ...DEFAULT_PARAMS, ...params })
  engine.run(seconds)
  return engine
}

describe('determinism', () => {
  it('replays identically from the same seed and settings', () => {
    const a = run({}, 300)
    const b = run({}, 300)
    expect(a.world.counts).toEqual(b.world.counts)
    expect(a.world.totals).toEqual(b.world.totals)
    expect(a.world.blobs.map((x) => [x.id, x.x, x.y, x.energy])).toEqual(b.world.blobs.map((x) => [x.id, x.x, x.y, x.energy]))
  })

  it('diverges when only the seed changes', () => {
    const a = run({ seed: 1234 }, 300)
    const b = run({ seed: 5678 }, 300)
    expect(a.world.blobs.map((x) => x.x)).not.toEqual(b.world.blobs.map((x) => x.x))
  })

  it('stepping by hand matches a headless run', () => {
    const a = new Engine({ ...DEFAULT_PARAMS })
    for (let i = 0; i < 600; i++) a.stepOnce()
    const b = run({}, 600 * DT)
    expect(a.world.counts).toEqual(b.world.counts)
  })
})

describe('energy rules', () => {
  it('blue starves with no fruit at all', () => {
    const w = run({ fruitGrowth: 0.01, fruitLimit: 1, trees: 1, redStart: 0, blueStart: 20 }, 600)
    expect(w.world.counts.blue).toBeLessThan(20)
    expect(w.world.totals.starved.blue).toBeGreaterThan(0)
  })

  it('red cannot live without blue to touch', () => {
    const w = run({ blueStart: 0, redStart: 12 }, 900)
    expect(w.world.counts.red).toBe(0)
    expect(w.world.totals.starved.red).toBeGreaterThan(0)
  })

  it('blue grows into an empty, fruit-rich garden', () => {
    const w = run({ redStart: 0, blueStart: 6, fruitGrowth: 0.28, fruitLimit: 12, trees: 26 }, 900)
    expect(w.world.counts.blue).toBeGreaterThan(6)
  })

  it('levels off instead of growing forever', () => {
    const w = run({ redStart: 0, blueStart: 6, fruitGrowth: 0.28, fruitLimit: 12, trees: 26 }, 2400)
    const s = w.history.samples
    const late = s.slice(Math.floor(s.length * 0.6)).map((x) => x.blue)
    const peak = Math.max(...s.map((x) => x.blue))
    expect(Math.max(...late)).toBeLessThan(peak * 1.6)
    expect(w.world.capReached).toBe(false)
  })

  it('eating moves energy from the tree to the blob', () => {
    const w = run({ redStart: 0, blueStart: 10 }, 240)
    expect(w.world.totals.fruitEaten).toBeGreaterThan(0)
  })

  it('a contact moves energy from blue to red', () => {
    const w = run({ blueStart: 40, redStart: 10 }, 240)
    expect(w.world.totals.contacts).toBeGreaterThan(0)
  })
})

describe('the garden holds together', () => {
  it('keeps both groups alive on the balanced preset', () => {
    const preset = PRESETS.find((p) => p.id === 'balanced')!
    const w = run(preset.params, 3000)
    expect(w.world.counts.blue).toBeGreaterThan(0)
    expect(w.world.counts.red).toBeGreaterThan(0)
  })

  it('produces real waves rather than a flat line', () => {
    const preset = PRESETS.find((p) => p.id === 'balanced')!
    const w = run(preset.params, 3000)
    const s = w.history.samples
    const blue = s.map((x) => x.blue)
    const smooth = movingAverage(blue, Math.round(s.length / 40))
    const mean = blue.reduce((a, b) => a + b, 0) / blue.length
    expect(findPeaks(smooth, mean * 0.28).length).toBeGreaterThanOrEqual(2)
  })

  it('low fruit keeps the garden small', () => {
    const low = run(PRESETS.find((p) => p.id === 'low-fruit')!.params, 1800)
    const rich = run(PRESETS.find((p) => p.id === 'fruit-rich')!.params, 1800)
    const peak = (e: typeof low) => Math.max(...e.history.samples.map((s) => s.blue))
    expect(peak(low)).toBeLessThan(peak(rich))
  })

  it('never exceeds the population cap', () => {
    const w = run({ fruitGrowth: 0.3, fruitLimit: 14, trees: 40, blueStart: 80, redStart: 20 }, 1200)
    expect(w.world.blobs.length).toBeLessThanOrEqual(CONST.populationCap)
  })

  it('red-heavy: blue dips first, then red fades', () => {
    const w = run(PRESETS.find((p) => p.id === 'red-heavy')!.params, 400)
    const s = w.history.samples
    const blueZero = s.find((x) => x.blue === 0)
    expect(blueZero).toBeTruthy()
    expect(blueZero!.red).toBeGreaterThan(0)
    expect(s[s.length - 1].red).toBeLessThan(blueZero!.red)
  })
})

describe('traits', () => {
  it('charges for speed, so it cannot run away for free', () => {
    const slowCost = costOver(1)
    const fastCost = costOver(1.6)
    expect(fastCost).toBeGreaterThan(slowCost)
  })

  function costOver(speedTrait: number) {
    const e = new Engine({ ...DEFAULT_PARAMS, blueStart: 12, redStart: 0, trees: 1, fruitGrowth: 0.01, fruitLimit: 1 })
    for (const b of e.world.blobs) b.traits.speed = speedTrait
    const before = e.world.blobs.reduce((s, b) => s + b.energy, 0)
    e.run(20)
    const after = e.world.blobs.reduce((s, b) => s + b.energy, 0)
    return before - after
  }
})

describe('analysis', () => {
  it('finds the lag between two shifted waves', () => {
    const a: number[] = []
    const b: number[] = []
    for (let i = 0; i < 400; i++) {
      a.push(Math.sin(i / 20))
      b.push(Math.sin((i - 12) / 20))
    }
    const lag = bestLag(a, b, 60)
    expect(lag).not.toBeNull()
    expect(lag!.lag).toBeGreaterThan(6)
    expect(lag!.lag).toBeLessThan(20)
  })

  it('calls out a group that faded', () => {
    const w = run({ blueStart: 0, redStart: 10 }, 900)
    const s = summarise({
      samples: w.history.samples,
      fruitCapacity: w.world.trees.length * w.params.fruitLimit,
      blueAlive: w.world.counts.blue,
      redAlive: w.world.counts.red,
    })
    expect(s.tone).toBe('faded')
  })
})

describe('params', () => {
  it('clamps to the declared range and rounds integers', () => {
    expect(clampParam('trees', 999)).toBe(44)
    expect(clampParam('trees', 3.7)).toBe(4)
    expect(clampParam('fruitGrowth', -1)).toBe(0.01)
  })
})

}

function steer(b: Blob, dx: number, dy: number, maxSpeed: number, dt: number, agility = 1) {
  const len = Math.hypot(dx, dy)
  let tx = 0
  let ty = 0
  if (len > 1e-6) {
    tx = (dx / len) * maxSpeed
    ty = (dy / len) * maxSpeed
  }
  const k = Math.min(1, CONST.turnRate * agility * dt)
  b.vx += (tx - b.vx) * k
  b.vy += (ty - b.vy) * k
  const sp = Math.hypot(b.vx, b.vy)
  if (sp > maxSpeed) {
    b.vx = (b.vx / sp) * maxSpeed
    b.vy = (b.vy / sp) * maxSpeed
  }
}

function applyMotion(world: World, b: Blob, dt: number) {
  b.x += b.vx * dt
  b.y += b.vy * dt
  const r = Math.hypot(b.x, b.y)
  const edge = world.radius - CONST.blobRadius - 2
  if (r > edge) {
    const nx = b.x / r
    const ny = b.y / r
    b.x = nx * edge
    b.y = ny * edge
    const dot = b.vx * nx + b.vy * ny
    b.vx -= nx * dot * 1.6
    b.vy -= ny * dot * 1.6
  }
}

function wanderVector(b: Blob, world: World, rng: Rng): { x: number; y: number } {
  if (rng.next() < 0.035) b.phase += rng.range(-0.9, 0.9)
  const drift = b.phase + Math.sin(world.t * 0.35 + b.id * 1.7) * 0.5
  let dx = Math.cos(drift)
  let dy = Math.sin(drift)
  const r = Math.hypot(b.x, b.y)
  const margin = world.radius * 0.82
  if (r > margin) {
    const push = (r - margin) / (world.radius - margin)
    dx -= (b.x / r) * push * 2.2
    dy -= (b.y / r) * push * 2.2
  }
  return { x: dx, y: dy }
}

function countCrowding(b: Blob, grid: Grid) {
  let n = 0
  const range2 = CONST.interferenceRange * CONST.interferenceRange
  grid.query(b.x, b.y, CONST.interferenceRange, (o) => {
    if (o === b || o.kind !== 'red') return
    const dx = o.x - b.x
    const dy = o.y - b.y
    if (dx * dx + dy * dy < range2) n++
  })
  b.crowding = n
}

function stepBlue(world: World, params: Params, b: Blob, grid: Grid, rng: Rng, dt: number) {
  if (b.actionTimer > 0) {
    b.vx *= 0.82
    b.vy *= 0.82
    applyMotion(world, b, dt)
    return
  }

  const vision = kindVision(params, b)
  const startled = b.panic > 0
  const hunger = 1 - clamp01(b.energy / (CONST.maxEnergy * 0.7))
  const nerve = 1 - CONST.hungerNerve * hunger
  const threatRange = vision * CONST.threatFactor * nerve * (startled ? CONST.panicRange : 1)
  const maxSpeed = kindSpeed(params, b) * (startled ? CONST.panicSpeed : 1)

  let fleeX = 0
  let fleeY = 0
  let threatWeight = 0
  let sepX = 0
  let sepY = 0
  let crowd = 0
  grid.query(b.x, b.y, Math.max(vision, CONST.separationRange), (o) => {
    if (o === b) return
    const dx = b.x - o.x
    const dy = b.y - o.y
    const d2 = dx * dx + dy * dy
    if (o.kind === 'red') {
      if (d2 < threatRange * threatRange && d2 > 1e-6) {
        const d = Math.sqrt(d2)
        const w = 1 - d / threatRange
        fleeX += (dx / d) * w
        fleeY += (dy / d) * w
        threatWeight += w
      }
    } else if (d2 < CONST.separationRange * CONST.separationRange && d2 > 1e-6) {
      const d = Math.sqrt(d2)
      const w = 1 - d / CONST.separationRange
      sepX += (dx / d) * w
      sepY += (dy / d) * w
      crowd += w
    }
  })

  let action: Action = 'wander'
  let dx = 0
  let dy = 0
  let agility = 1

  if (threatWeight > 0.02) {
    action = 'flee'
    agility = 1.6
    dx = fleeX * 3 + sepX * 0.4
    dy = fleeY * 3 + sepY * 0.4
    const w = wanderVector(b, world, rng)
    dx += w.x * 0.35
    dy += w.y * 0.35
  } else {
    let best = -1
    let bestScore = -Infinity
    let bestDist = 0
    let nearestTree = -1
    let nearestDist = Infinity
    for (const tree of world.trees) {
      const d = Math.hypot(tree.x - b.x, tree.y - b.y)
      if (d > vision) continue
      if (d < nearestDist) {
        nearestDist = d
        nearestTree = tree.id
      }
      if (tree.fruit <= 0) continue
      let score = tree.fruit / (d + 34)
      if (tree.id === b.targetTree) score *= 1.28
      if (score > bestScore) {
        bestScore = score
        best = tree.id
        bestDist = d
      }
    }

    if (best >= 0) {
      const tree = world.trees[best]
      b.targetTree = best
      const reach = CONST.eatReach + 8 * tree.scale
      if (bestDist <= reach && tree.fruit > 0) {
        tree.fruit--
        tree.delay = params.fruitDelay
        b.action = 'eat'
        b.actionTimer = params.blueEatTime
        b.actionTotal = params.blueEatTime
        b.squash = 0.5
        b.vx *= 0.3
        b.vy *= 0.3
        applyMotion(world, b, dt)
        return
      }
      action = 'seek'
      dx = tree.x - b.x
      dy = tree.y - b.y
      const len = Math.hypot(dx, dy) || 1
      dx /= len
      dy /= len
      if (crowd > 0.6) {
        dx += sepX * 1.1
        dy += sepY * 1.1
        action = 'avoid'
      }
    } else if (crowd > 1.1) {
      action = 'avoid'
      dx = sepX * 2
      dy = sepY * 2
      const w = wanderVector(b, world, rng)
      dx += w.x * 0.5
      dy += w.y * 0.5
    } else if (nearestTree >= 0) {
      const tree = world.trees[nearestTree]
      const toTree = Math.hypot(tree.x - b.x, tree.y - b.y)
      action = 'gather'
      b.targetTree = nearestTree
      const w = wanderVector(b, world, rng)
      const pull = toTree > 46 ? 1.1 : -0.25
      dx = ((tree.x - b.x) / (toTree || 1)) * pull + w.x * 0.9 + sepX * 0.6
      dy = ((tree.y - b.y) / (toTree || 1)) * pull + w.y * 0.9 + sepY * 0.6
    } else {
      action = 'wander'
      b.targetTree = -1
      const w = wanderVector(b, world, rng)
      dx = w.x + sepX * 0.5
      dy = w.y + sepY * 0.5
    }
  }

  b.action = action
  const cruise = action === 'gather' ? maxSpeed * 0.55 : maxSpeed
  steer(b, dx, dy, cruise, dt, agility)
  applyMotion(world, b, dt)
}

function stepRed(world: World, params: Params, b: Blob, grid: Grid, rng: Rng, dt: number) {
  countCrowding(b, grid)
  if (b.actionTimer > 0) {
    b.vx *= b.action === 'contact' ? 0.75 : 0.88
    b.vy *= b.action === 'contact' ? 0.75 : 0.88
    applyMotion(world, b, dt)
    return
  }

  const vision = kindVision(params, b)
  const maxSpeed = kindSpeed(params, b)

  let target: Blob | null = null
  let bestScore = -Infinity
  let sepX = 0
  let sepY = 0
  grid.query(b.x, b.y, Math.max(vision, CONST.separationRange), (o) => {
    if (o === b) return
    const dx = o.x - b.x
    const dy = o.y - b.y
    const d2 = dx * dx + dy * dy
    if (o.kind === 'blue') {
      const reach = o.sheltered && o.action !== 'eat' ? vision * CONST.shelterFactor : vision
      if (d2 > reach * reach) return
      if (o.immunity > 0) return
      const d = Math.sqrt(d2)
      let score = 1 - d / vision
      if (o.action === 'eat') score += 1.2
      else if (o.action === 'gather' || o.action === 'seek') score += 0.2
      if (o.id === b.targetBlob) score += 0.18
      if (score > bestScore) {
        bestScore = score
        target = o
      }
    } else if (d2 < CONST.separationRange * CONST.separationRange && d2 > 1e-6) {
      const d = Math.sqrt(d2)
      const w = 1 - d / CONST.separationRange
      sepX -= (dx / d) * w
      sepY -= (dy / d) * w
    }
  })

  let action: Action = 'wander'
  let dx = 0
  let dy = 0

  const prey = target as Blob | null
  if (prey) {
    const d = Math.hypot(prey.x - b.x, prey.y - b.y)
    b.targetBlob = prey.id
    if (d <= CONST.contactReach) {
      const taken = Math.min(params.redStrength, Math.max(0, prey.energy))
      prey.energy -= params.redStrength
      prey.squash = 0.85
      prey.glow = 0.5
      prey.immunity = CONST.contactImmunity
      prey.panic = CONST.panicTime
      if (prey.action === 'eat') {
        prey.action = 'flee'
        prey.actionTimer = 0
      }
      b.energy = Math.min(CONST.maxEnergy, b.energy + taken * CONST.contactEfficiency)
      b.meals++
      b.glow = 0.9
      b.squash = 0.6
      b.action = 'contact'
      b.actionTimer = CONST.contactTime
      b.actionTotal = CONST.contactTime + params.redPause
      world.totals.contacts++
      addEffect(world, {
        kind: 'contact',
        x: (b.x + prey.x) / 2,
        y: (b.y + prey.y) / 2,
        z: 9,
        life: 0.65,
        color: 'red',
        seed: b.id * 7 + world.steps,
      })
      b.vx *= 0.2
      b.vy *= 0.2
      applyMotion(world, b, dt)
      return
    }
    action = 'hunt'
    dx = (prey.x - b.x) / (d || 1) + sepX * 0.35
    dy = (prey.y - b.y) / (d || 1) + sepY * 0.35
  } else {
    b.targetBlob = -1
    action = 'wander'
    const w = wanderVector(b, world, rng)
    dx = w.x + sepX * 0.6
    dy = w.y + sepY * 0.6
  }

  b.action = action
  const thin = 1 - clamp01(b.energy / (CONST.maxEnergy * 0.5))
  const cruise = action === 'hunt' ? maxSpeed : maxSpeed * (0.72 - 0.34 * thin)
  steer(b, dx, dy, cruise, dt, action === 'hunt' ? 1.2 : 1)
  applyMotion(world, b, dt)
}

function tryCopy(world: World, params: Params, b: Blob, born: Blob[], rng: Rng) {
  const threshold = b.kind === 'blue' ? params.blueCopy : params.redCopy
  if (b.energy < threshold) return
  if (world.blobs.length + born.length >= CONST.populationCap) {
    world.capReached = true
    return
  }
  const share = (b.energy * (1 - CONST.birthCost)) / 2
  b.energy = share
  b.copyCooldown = CONST.copyCooldown
  b.children++

  const a = rng.next() * TAU
  const off = CONST.blobRadius * 1.6
  const child = makeBlob(
    world.nextId++,
    b.kind,
    b.x + Math.cos(a) * off,
    b.y + Math.sin(a) * off,
    share,
    {
      speed: mutate(b.traits.speed, rng),
      vision: mutate(b.traits.vision, rng),
      thrift: mutate(b.traits.thrift, rng),
    },
    rng,
    world.t,
    b.generation + 1,
    b.id,
  )
  child.copyCooldown = CONST.copyCooldown
  born.push(child)
  world.totals.births[b.kind]++
  addEffect(world, { kind: 'birth', x: b.x, y: b.y, z: 9, life: 0.55, color: b.kind, seed: child.id })
}

export function meanEnergy(world: World, kind: Kind): number {
  let sum = 0
  let n = 0
  for (const b of world.blobs) {
    if (b.kind !== kind) continue
    sum += b.energy
    n++
  }
  return n ? sum / n : 0
}

