:root {
  color: #241c16;
  background: #e7d5bf;
  font-family: ui-rounded, "Avenir Next", "Segoe UI", sans-serif;
  font-size: 14px;
  line-height: 1.4;
  --paper: #fffaf4;
  --ink: #241c16;
  --muted: #5c4e42;
  --line: #eadccb;
  --moss: #2c6b3c;
  --shadow: 0 6px 10px rgba(70, 46, 24, 0.08);
  --radius: 16px;
}

* { box-sizing: border-box; }

html, body, #root {
  margin: 0;
  height: 100%;
}

button, input { font: inherit; color: inherit; }

.app {
  height: 100dvh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  background:
    radial-gradient(circle at 50% 0%, #f4e7d4 0%, #e7d5bf 42%, #d9c3a6 100%);
}

.top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  padding: 10px 14px 8px;
}

h1 {
  margin: 0;
  font-size: 1.45rem;
  letter-spacing: -0.03em;
  font-weight: 700;
}

h2, h3 { margin: 0; font-size: 0.95rem; letter-spacing: -0.02em; }
h3 { font-size: 0.8rem; color: var(--muted); }

.transport, .live, .speed, .preset-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.transport button, .inspector button, .preset {
  border: 0;
  background: var(--paper);
  border-radius: 999px;
  padding: 6px 10px;
  box-shadow: var(--shadow);
  cursor: pointer;
}

.transport button[aria-pressed="true"] {
  background: var(--moss);
  color: #f4fff6;
}

.speed { color: var(--muted); gap: 8px; }
.speed input { width: 110px; }
.speed b { color: var(--ink); min-width: 2.2rem; }

.live { margin-left: auto; gap: 12px; }
.live strong { font-variant-numeric: tabular-nums; }

.swatch {
  display: inline-block;
  width: 9px;
  height: 9px;
